ruleToc.chapterList:
@js:
//java.log(result)
function spArr(arr, num){
	let newArr = []
	for(let i = 0; i < arr.length;){
		newArr.push(arr.slice(i, i += num))
	}
	return newArr
}
let res = JSON.parse(result).data
let item_list = spArr(res["item_list"], 100)
let array = []
let book_id = res.book_info.book_id;
for(let i = 0; i < item_list.length; i ++){
	let response = java.ajax('https://novel.snssdk.com/api/novel/book/directory/detail/v1/?item_ids='+item_list[i]);
	if((book_id=="7182286100432423976") && (item_list[i].includes("7211874965795602984"))){
        response = response.replace("\\微笑","😊");
	}
	let data = JSON.parse(response).data
	data.forEach((x) => {
		array.push({
			name: x.title,
			url: 'https://novel.snssdk.com/api/novel/book/reader/full/v1/?item_id='+x.item_id+'&aid=2329',
			info: ((Number(x.volume_name)==0?"第一卷：默认":x.volume_name)+' • '+java.timeFormat(x.first_pass_time*1000)+' • '+x.chapter_word_number+'字')
		})
	})
}
array

exploreUrl:
@js:
sort = cache.getFile('KuwoNovels');
if(sort==null){
var fk = sk = 1,
sort1 = [],
sort2 = [];
push=(title,url,type1,type2)=>{
		json = JSON.stringify({
				title: title,
				url: url?url:"",
				style: {
						layout_flexGrow: 1,
						layout_flexBasisPercent: type1
					}
			});
		return  eval('sort'+type2+'.push(json)');
	}
$$=(freetype,category_id,fk,sk)=>`http://appi.kuwo.cn/novels/api/book/category/${freetype}?category_id=${category_id}&fk=${fk}&sk=${sk}&pi={{page}\}&ps=20`;

JSON.parse(java.ajax('http://appi.kuwo.cn/novels/api/book/categories')).data.map($=>{
		freetype = $.freetype
		if(freetype==3)return;

		push('༺ˇ»`ʚ'+$.freetype_name+'ɞ´«ˇ༻', null, 1, freetype);
		$.categories.map($=>{
				category_id = $.category_id
				push('༺ '+$.category_name+' ༻', $$(freetype,category_id,sk,fk), 1, freetype);
				["综合", "热门", "最新"].map((title,sk)=>{
						sk++
						['['+title+']', '完结', '连载'].map((title,fk)=>{
								fk++
								push(title, $$(freetype,category_id,sk,fk), 0.25, freetype);
							});
					});
			});
	});
sort = sort1.concat(sort2);
cache.putFile('KuwoNovels', sort, 6E6);
}
'['+sort.toString()+']'

